sql_calls.sql:
SELECT COUNT(*) AS intersect_users FROM (
  SELECT DISTINCT o.user_id FROM payments p JOIN orders o ON o.id = p.order_id WHERE p.method = '微信'
) a
JOIN (
  SELECT DISTINCT o.user_id FROM orders o JOIN order_items oi ON oi.order_id = o.id JOIN products pr ON pr.id = oi.product_id WHERE pr.category = '图书'
) b ON a.user_id = b.user_id;

